package practice;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

/**
 * One user session of the admin console. While it is open it hears about every configuration
 * change, so its screens can refresh; a closed session must hear nothing and leave no trace in
 * the watcher, which lives as long as the server.
 */
public class ConfigSession {

    /** The server-wide watcher. Given: don't change it. */
    public static final class ConfigWatcher {
        private final List<Consumer<String>> listeners = new CopyOnWriteArrayList<>();

        public void subscribe(Consumer<String> listener) {
            listeners.add(listener);
        }

        public void unsubscribe(Consumer<String> listener) {
            listeners.remove(listener);
        }

        public void changed(String key) {
            for (Consumer<String> listener : listeners) {
                listener.accept(key);
            }
        }

        public int listenerCount() {
            return listeners.size();
        }
    }

    private final ConfigWatcher watcher;
    private final List<String> heard = new ArrayList<>();
    private final Consumer<String> listener = key -> onChange(key);

    public ConfigSession(ConfigWatcher watcher) {
        this.watcher = watcher;
    }

    void onChange(String key) {
        heard.add(key);
    }

    /** The keys this session has heard about, in order. */
    public List<String> heard() {
        return heard;
    }

    /** From now on, this session hears about every change. */
    public void open() {
        watcher.subscribe(listener);
    }

    /** From now on, this session hears nothing, and the watcher holds nothing of it. */
    public void close() {
        watcher.unsubscribe(listener);
    }
}

package practice;

import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            ConfigSession.ConfigWatcher watcher = new ConfigSession.ConfigWatcher();
            ConfigSession alice = new ConfigSession(watcher);
            ConfigSession bob = new ConfigSession(watcher);
            alice.open();
            bob.open();
            watcher.changed("theme.color");
            System.out.println("listeners while both are open: " + watcher.listenerCount());
            alice.close();
            watcher.changed("upload.limit");
            System.out.println("first session heard: " + alice.heard());
            System.out.println("second session heard: " + bob.heard());
            System.out.println("listeners after one close: " + watcher.listenerCount());
            bob.close();
            System.out.println("listeners after both close: " + watcher.listenerCount());
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

